fn is_prime(n: i8) -> bool {
    // By definition, primes are integers ≥ 2
    if n < 2 {
        return false;
    }

    // Try all possible divisors k in [2, n)
    let mut k: i8 = 2;
    while k < n {
        if n % k == 0 {
            return false;
        }
        k += 1;
    }

    // No divisor found → n is prime
    true
}

